import XCTest

final class FeedsTapTests: XCTestCase {
    func testOpenFeedsTab() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 2) {
            openButton.tap()
        }
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        let feeds = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'Feeds'")).firstMatch
        if feeds.waitForExistence(timeout: 8) {
            feeds.tap()
        } else {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.72, dy: 0.15)).tap()
        }
        sleep(2)
    }
}
